<?php namespace App\Http\Controllers; use App\Models\Category; use App\Models\CatalogItem; use App\Models\InventoryUnit; use Illuminate\Http\Request; class InventoryController extends Controller { public function index(){return view('inventory.index',['categories'=>Category::all(),'products'=>CatalogItem::where('type','product')->get(),'units'=>InventoryUnit::with('item')->latest()->get()]);} public function category(Request $r){Category::create($r->validate(['name'=>['required','unique:categories,name']]));return back();} public function unit(Request $r){InventoryUnit::create($r->validate(['catalog_item_id'=>['required','exists:catalog_items,id'],'serial_number'=>['required','unique:inventory_units,serial_number']]));return back();} }
